/** currentColor 类图标的品牌默认色；未列出的图标自带内联 fill。 */
/**
 * 单色 logo 的品牌色。**只登记真彩色**——纯黑/纯白这类"其实是墨色"的品牌
 * 不要写死，留空让它跟随 currentColor，调用方给 `text-ink` 即可自动适配明暗两套
 * 主题。写死 #000 的后果是暗色下整个图形沉进深色底里，肉眼看不出那格有图标。
 */
const ICON_DEFAULT_COLOR: Record<string, string> = {
  anthropic: "#D4915D",
  bailian: "#624AFF",
  groq: "#F55036",
  mistral: "#FA520F",
};

/**
 * 名称子串 → 图标推断表（对齐 cc-switch iconInference）。
 * 顺序即优先级：先精确品牌，再宽泛别名。
 */
const NAME_ICON_RULES: Array<[substring: string, icon: string]> = [
  ["anthropic", "anthropic"],
  ["claude", "anthropic"],
  ["openai", "openai"],
  ["codex", "openai"],
  ["deepseek", "deepseek"],
  ["zhipu", "zhipu"],
  ["glm", "zhipu"],
  ["bigmodel", "zhipu"],
  ["智谱", "zhipu"],
  ["qwen", "qwen"],
  ["通义", "qwen"],
  ["bailian", "bailian"],
  ["百炼", "bailian"],
  ["dashscope", "bailian"],
  ["kimi", "kimi"],
  ["moonshot", "kimi"],
  ["月之暗面", "kimi"],
  ["minimax", "minimax"],
  ["siliconflow", "siliconflow"],
  ["silicon", "siliconflow"],
  ["硅基", "siliconflow"],
  ["openrouter", "openrouter"],
  ["modelscope", "modelscope"],
  ["魔搭", "modelscope"],
  ["longcat", "longcat"],
  ["baidu", "baidu"],
  ["qianfan", "baidu"],
  ["百度", "baidu"],
  ["stepfun", "stepfun"],
  ["阶跃", "stepfun"],
  ["doubao", "doubao"],
  ["豆包", "doubao"],
  ["volcengine", "doubao"],
  ["火山", "doubao"],
  ["hunyuan", "hunyuan"],
  ["混元", "hunyuan"],
  ["tencent", "tencent"],
  ["腾讯", "tencent"],
  ["mimo", "xiaomimimo"],
  ["xiaomi", "xiaomimimo"],
  ["小米", "xiaomimimo"],
  ["novita", "novita"],
  ["nvidia", "nvidia"],
  ["gemini", "gemini"],
  ["google", "gemini"],
  ["grok", "grok"],
  ["xai", "grok"],
  ["x.ai", "grok"],
  ["groq", "groq"],
  ["together", "together"],
  ["fireworks", "fireworks"],
  ["cerebras", "cerebras"],
  ["deepinfra", "deepinfra"],
  ["mistral", "mistral"],
  ["aihubmix", "aihubmix"],
  ["azure", "azure"],
  ["computetoken", "computetoken"],
  ["compute token", "computetoken"],
];

/** key 是否有内置 SVG（预设 icon 的守卫测试用）。 */
export function hasBuiltinIcon(key: string): boolean {
  return key in ICON_SVG;
}

/** 按供应商名称推断内置图标 key；无匹配返回 null（走首字母兜底）。 */
export function inferProviderIcon(name: string): string | null {
  const lower = name.toLowerCase();
  for (const [substring, icon] of NAME_ICON_RULES) {
    if (lower.includes(substring)) return icon;
  }
  return null;
}

/** 首字母缩写（最多 2 位），如 "My Relay" → "MR"。 */
function initialsOf(name: string): string {
  return (
    name
      .split(/\s+/)
      .filter(Boolean)
      .map((word) => word[0])
      .join("")
      .toUpperCase()
      .slice(0, 2) || "?"
  );
}

export function ProviderIcon({
  name,
  icon,
  size = 20,
  plate = false,
  flat = false,
  className,
}: {
  /** 供应商名称：无显式 icon 时用于推断与首字母兜底。 */
  name: string;
  /** 显式图标 key（预设携带）；缺省按 name 推断。 */
  icon?: string | null;
  size?: number;
  /**
   * 白色衬底：品牌 SVG 多为硬编码品牌色（如 Compute Token 的 #0968F5），
   * 放到深色/品牌色底上会与底色糊成一片。选中态传 plate 保留原色又保证可辨。
   */
  plate?: boolean;
  /**
   * 去掉首字母兜底自带的灰底，改为继承外层颜色。调用方本身就是一块图标板时
   * （如 SheetHero），不加这个就是灰板里套一块灰板。
   */
  flat?: boolean;
  className?: string;
}) {
  const resolved = useMemo(() => icon ?? inferProviderIcon(name), [icon, name]);
  const svg = resolved ? ICON_SVG[resolved] : undefined;

  if (svg) {
    return (
      <span
        className={cn(
          "inline-flex shrink-0 items-center justify-center",
          plate && "rounded-[5px] bg-white ring-1 ring-black/5",
          className,
        )}
        style={{
          width: size,
          height: size,
          // 衬底占掉四周留白，图形按比例缩小才不会顶到板边。
          fontSize: plate ? Math.round(size * 0.76) : size,
          lineHeight: 1,
          // currentColor 型图标（多数品牌单色 SVG）在白板上会继承按钮的白字而消失，
          // 无品牌色时按白板兜底成墨色。
          color: ICON_DEFAULT_COLOR[resolved ?? ""] ?? (plate ? "#0f172a" : undefined),
        }}
        title={name}
        aria-hidden
        // biome-ignore lint/security/noDangerouslySetInnerHtml: 图标为内置静态 SVG 常量，非用户输入
        dangerouslySetInnerHTML={{ __html: svg }}
      />
    );
  }

  return (
    <span
      className={cn(
        "inline-flex shrink-0 items-center justify-center rounded-md font-semibold",
        plate
          ? // 字色跟未选中态同为主色：白衬底是为了在实心主色底上站住，不是要把
            // 首字母换成另一种颜色——蓝板蓝字 → 白板灰字的跳变太跳。
            "bg-white text-accent ring-1 ring-black/5"
          : flat
            ? "text-current"
            : // 首字母兜底走主色而不是中性灰：认不出品牌不代表这一项该是灰的，
              // 一列品牌 logo 里夹几块灰方块，看着像没加载出来。
              "bg-accent-soft text-accent",
        className,
      )}
      style={{ width: size, height: size, fontSize: Math.max(size * 0.42, 10) }}
      title={name}
      aria-hidden
    >
      {initialsOf(name)}
    </span>
  );
}
